282	  /**
283	   * Registers an agent definition. If an agent with the same name exists,
284	   * it will be overwritten, respecting the precedence established by the
285	   * initialization order.
286	   */
287	  protected async registerAgent<TOutput extends z.ZodTypeAny>(
288	    definition: AgentDefinition<TOutput>,
289	  ): Promise<void> {
290	    if (definition.kind === 'local') {
291	      this.registerLocalAgent(definition);
292	    } else if (definition.kind === 'remote') {
293	      await this.registerRemoteAgent(definition);
294	    }
