297	  /**
298	   * Registers a local agent definition synchronously.
299	   */
300	  protected registerLocalAgent<TOutput extends z.ZodTypeAny>(
301	    definition: AgentDefinition<TOutput>,
302	  ): void {
303	    if (definition.kind !== 'local') {
304	      return;
305	    }
306	
307	    // Basic validation
308	    if (!definition.name || !definition.description) {
309	      debugLogger.warn(
310	        `[AgentRegistry] Skipping invalid agent definition. Missing name or description.`,
311	      );
312	      return;
313	    }
314	
315	    this.allDefinitions.set(definition.name, definition);
316	
317	    const settingsOverrides =
318	      this.config.getAgentsSettings().overrides?.[definition.name];
319	
320	    if (!this.isAgentEnabled(definition, settingsOverrides)) {
321	      if (this.config.getDebugMode()) {
322	        debugLogger.log(
323	          `[AgentRegistry] Skipping disabled agent '${definition.name}'`,
324	        );
325	      }
326	      return;
327	    }
328	
329	    if (this.agents.has(definition.name) && this.config.getDebugMode()) {
330	      debugLogger.log(`[AgentRegistry] Overriding agent '${definition.name}'`);
331	    }
332	
333	    const mergedDefinition = this.applyOverrides(definition, settingsOverrides);
334	    this.agents.set(mergedDefinition.name, mergedDefinition);
335	
336	    this.registerModelConfigs(mergedDefinition);
337	    this.addAgentPolicy(mergedDefinition);
338	  }
