340	  private addAgentPolicy(definition: AgentDefinition<z.ZodTypeAny>): void {
341	    const policyEngine = this.config.getPolicyEngine();
342	    if (!policyEngine) {
343	      return;
344	    }
345	
346	    // If the user has explicitly defined a policy for this tool, respect it.
347	    // ignoreDynamic=true means we only check for rules NOT added by this registry.
348	    if (policyEngine.hasRuleForTool(definition.name, true)) {
349	      if (this.config.getDebugMode()) {
350	        debugLogger.log(
351	          `[AgentRegistry] User policy exists for '${definition.name}', skipping dynamic registration.`,
352	        );
