/** Priority for browser agent sensitive-action confirmation rules. */
const PRIORITY_BROWSER_CONFIRM = 999;

/** Read-only browser tools that are always allowed without confirmation. */
const BROWSER_READ_ONLY_TOOLS = [
  'take_snapshot',
  'take_screenshot',
  'list_pages',
];

/**
 * Sensitive browser tools that require user confirmation when
 * `agents.browser.confirmSensitiveActions` is enabled.
 */
const BROWSER_SENSITIVE_TOOLS = ['fill', 'upload_file', 'evaluate_script'];

/**
 * Registers policy rules for the browser agent's tools.
 *
 * - Read-only tools (snapshot, screenshot, list_pages) are always ALLOWED.
 * - When `confirmSensitiveActions` is enabled, sensitive tools (fill,
 *   upload_file, evaluate_script) require user confirmation (ASK_USER).
 * - `fill` always has a rule registered regardless of configuration.
 */
function registerBrowserPolicyRules(config: Config): void {
  const policyEngine = config.getPolicyEngine();
  if (!policyEngine) {
    return;
  }

  const browserConfig = config.getBrowserAgentConfig();
  const confirmSensitiveActions =
    browserConfig.customConfig.confirmSensitiveActions === true;

  const qualify = (toolName: string) =>
    `${MCP_TOOL_PREFIX}${BROWSER_AGENT_NAME}_${toolName}`;

  // Read-only tools are always allowed.
  for (const toolName of BROWSER_READ_ONLY_TOOLS) {
    policyEngine.addRule({
      toolName: qualify(toolName),
      mcpName: BROWSER_AGENT_NAME,
      decision: PolicyDecision.ALLOW,
      priority: PRIORITY_SUBAGENT_TOOL,
      source: 'BrowserAgentFactory',
    });
  }

  // Sensitive tools require confirmation when enabled. `fill` always gets a
  // rule; the other sensitive tools are only registered when confirmation is on.
  for (const toolName of BROWSER_SENSITIVE_TOOLS) {
    if (confirmSensitiveActions) {
      policyEngine.addRule({
        toolName: qualify(toolName),
        mcpName: BROWSER_AGENT_NAME,
        decision: PolicyDecision.ASK_USER,
        priority: PRIORITY_BROWSER_CONFIRM,
        source: 'BrowserAgentFactory',
      });
    } else if (toolName === 'fill') {
      policyEngine.addRule({
        toolName: qualify(toolName),
        mcpName: BROWSER_AGENT_NAME,
        decision: PolicyDecision.ALLOW,
        priority: PRIORITY_SUBAGENT_TOOL,
        source: 'BrowserAgentFactory',
      });
    }
  }
}

